// Ambil output teks dari AI Agent
let outputText = $input.first().json.output || "";

// 1. Hapus jika formatnya memakai tag <think>...</think>
outputText = outputText.replace(/<think>[\s\S]*?<\/think>/gi, '');

// 2. Hapus jika AI menulis "Here's a thinking process: ..." hingga batas jawaban asli
if (outputText.includes("Here's a thinking process:")) {
  // Potong teks dan ambil bagian paling akhir setelah pemikiran selesai
  let lines = outputText.split("\n\n");
  // Mengambil paragraf/bagian respon bersih di baris akhir
  outputText = lines.slice(-1)[0]; 
}

// 3. Bersihkan sisa spasi atau enter liar
let cleanedText = outputText.trim();

// Kembalikan objek JSON yang bersih
return [{
  json: {
    status: "success",
    message: cleanedText
  }
}];

const inputData = $input.first().json;
const body = inputData.body || inputData;

const sessionId = body.session_id || "default_session";
const userMessage = body.message || "";
const chatHistory = body.history || []; // Kosong jika sesi biasa (tanpa project)

// 1. Filter pesan canceled & format history dari sesi saudara
let formattedHistory = "";
if (Array.isArray(chatHistory) && chatHistory.length > 0) {
  formattedHistory = chatHistory
    .filter(h => !h.is_canceled) // Mengabaikan pesan yang dibatalkan user
    .map(h => `${h.role === 'user' ? 'User' : 'AI'}: ${h.content}`)
    .join('\n');
}

// 2. Susun prompt gabungan
let combinedPrompt = userMessage;
if (formattedHistory) {
  combinedPrompt = `Konteks dari sesi lain di proyek ini:\n${formattedHistory}\n\nPertanyaan User saat ini:\n${userMessage}`;
}

// 3. Hash rute untuk 3 cabang AI Agent (0, 1, 2)
function hashCode(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash);
}

const assignedRoute = hashCode(String(sessionId)) % 3;

return [{
  json: {
    ...inputData,
    message: combinedPrompt, // Dikirim ke AI Agent
    assigned_route: assignedRoute
  }
}];

// Ambil tanggal hari ini (YYYY-MM-DD)
