const formattedPrompt = `[WAKTU SERVER: Hari ini tanggal ${todayDate}]\n\nPertanyaan User:\n${userPrompt}`;

return {
  json: {
    ...$input.first().json,
    chatInput: formattedPrompt
  }
};

