const input = $input.first().json;
const sessionId = $('Webhook').item.json.body.session_id;

// 1. Format tanggal aman (default ke hari ini jika AI tidak kirim)
const eventDate = input.date || new Date().toISOString().split('T')[0];

// 2. Format jam mulai (pastikan format HH:mm)
let startTime = input.start_time || '08:00';
if (startTime.length > 5) startTime = startTime.substring(0, 5);

// 3. Autogenerate jam selesai jika AI tidak mengirimkan end_time
let endTime = input.end_time;
if (!endTime) {
  const [hours, minutes] = startTime.split(':');
  const endHour = String((parseInt(hours, 10) + 1) % 24).padStart(2, '0');
  endTime = `${endHour}:${minutes || '00'}`;
} else if (endTime.length > 5) {
  endTime = endTime.substring(0, 5);
}

// 4. Susun payload sesuai harapan API Laravel
const payload = {
  title: input.title,
  subject: input.subject || 'Umum',
  date: eventDate,
  start_time: startTime, // Hasil: "13:00"
  end_time: endTime     // Hasil: "15:00"
};

const options = {
  method: 'POST',
  url: 'https://studyplanner.web.id/api/ai/tool/calendar',
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
    'X-API-KEY': 'Laravel_n8n_SecretKey_998877',
    'X-SESSION-ID': sessionId
  },
  body: payload,
  json: true
};

try {
  const response = await this.helpers.httpRequest(options);
  return JSON.stringify(response);
} catch (error) {
  // Mengembalikan detail validasi Laravel jika tetap 422
  return JSON.stringify({
    status: 'error',
    message: error.response?.data || error.message
  });
}

