  });
} catch (error) {
  return JSON.stringify({
    status: 'error',
    message: error.message
  });
}

// 1. Ambil input parameter yang dikirim oleh AI Agent
const input = $input.first().json;

// 2. Ambil session_id langsung dari context atau fallback aman
let sessionId = "default_session";
try {
  sessionId = $('Webhook').first().json.body?.session_id || $('Webhook').first().json.session_id || "default_session";
} catch (e) {
  // Jika Webhook node tidak terjangkau, gunakan fallback dari input
  sessionId = input.session_id || "default_session";
}

// 3. Susun payload sesuai kebutuhan API Laravel
const payload = {
  title: input.title || input.name || 'Jadwal Baru',
  subject: input.subject || 'Umum',
  date: input.date,             // YYYY-MM-DD
  start_time: input.start_time, // HH:mm
  end_time: input.end_time       // HH:mm
};

// 4. Kirim request menggunakan fetch standar
const response = await fetch('https://studyplanner.web.id/api/ai/tool/calendar', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
    'X-API-KEY': 'Laravel_n8n_SecretKey_998877',
    'X-SESSION-ID': String(sessionId)
  },
  body: JSON.stringify(payload)
});

const result = await response.json();

return JSON.stringify({
  status: response.ok ? 'success' : 'error',
  data: result
});

